<template><div class="bar-chart"><div v-for="(row,i) in sorted" :key="row.lab_id || row.lab_code" class="bar-row"><span :title="row.lab_name">{{ row.lab_name }}</span><div class="bar-track"><div class="bar-fill" :class="'color-'+i%3" :style="{width: (Number(row.person_hours)/max*100)+'%'}"></div></div><strong>{{ Number(row.person_hours).toLocaleString('zh-CN') }}</strong></div><div v-if="!sorted.length" class="empty"><strong>所选范围暂无排课</strong></div><div class="chart-axis"><span>按实际排课统计</span><span>单位：人时</span></div></div></template>
<script>export default { props:{rows:{default:()=>[]}},computed:{sorted(){return this.rows.slice().sort((a,b)=>Number(b.person_hours)-Number(a.person_hours))},max(){return Math.max(1,...this.rows.map(r=>Number(r.person_hours)||0))}} }</script>
